-- Baseline (#268): every api/db/*.sql of main before migrations, concatenated in their old load order.
-- Idempotent on purpose: a database built before migrations (prod) runs it once on adoption and only gains
-- what it was missing. Later migrations need not be idempotent.

-- ── better-auth.sql ──

-- Generated by `pnpm auth:generate` in web/ (Better Auth CLI, Kysely/Postgres). Do not edit by hand.

create table if not exists "user" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "name" text not null, "email" text not null unique, "emailVerified" boolean not null, "image" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null, "role" text, "banned" boolean, "banReason" text, "banExpires" timestamptz);

create table if not exists "session" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "expiresAt" timestamptz not null, "token" text not null unique, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null, "ipAddress" text, "userAgent" text, "userId" uuid not null references "user" ("id") on delete cascade, "impersonatedBy" text);

create table if not exists "account" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "accountId" text not null, "providerId" text not null, "userId" uuid not null references "user" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, "scope" text, "password" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null);

create table if not exists "verification" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "identifier" text not null, "value" text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);

create table if not exists "jwks" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "publicKey" text not null, "privateKey" text not null, "createdAt" timestamptz not null, "expiresAt" timestamptz, "alg" text, "crv" text);

create index if not exists "session_userId_idx" on "session" ("userId");

create index if not exists "account_userId_idx" on "account" ("userId");

create index if not exists "verification_identifier_idx" on "verification" ("identifier");

-- ── schema.sql ──

-- ============================================================================
-- zenbree app schema (Postgres 17). Runs AFTER db/better-auth.sql: every
-- user FK points at Better Auth's "user"(id), uuid (generateId: "uuid").
--
-- Dropped: RLS policies, Supabase grants/roles, auth.users, pg_cron (→ beat).
--
-- No signup trigger: user_credits rows are created by the web app's Better
-- Auth hook (databaseHooks.user.create.after).
--
-- Idempotent (IF NOT EXISTS / OR REPLACE): safe to re-run.
-- ============================================================================

-- ── Credits ────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS user_credits (
    user_id              UUID PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,
    credits_remaining    INTEGER NOT NULL DEFAULT 50,
    onboarding_free_used INTEGER NOT NULL DEFAULT 0,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Ledger: full audit trail. user_credits.credits_remaining is the hot path;
-- this is the source of truth for reconciliation and reporting.
CREATE TABLE IF NOT EXISTS credit_transactions (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    type            TEXT NOT NULL CONSTRAINT credit_transactions_type_check CHECK (type IN (
                        'deduction', 'refund', 'renewal', 'purchase',
                        'bonus', 'adjustment', 'reservation'
                    )),
    amount          INTEGER NOT NULL CHECK (amount > 0),
    balance_after   INTEGER NOT NULL,
    -- 'settling' = work landed but the settle failed; the reaper must not
    -- release it.
    status          TEXT NOT NULL DEFAULT 'committed'
                    CONSTRAINT credit_transactions_status_check
                    CHECK (status IN ('committed', 'reserved', 'released', 'settling')),
    reference_type  TEXT,
    reference_id    TEXT,
    description     TEXT,
    tool_name       TEXT,
    session_id      UUID,
    -- Written once by settle_reservation_with_slack; makes retries idempotent.
    settlement_refund_amount INT,
    settlement_net_credits   INT,
    settlement_balance_after INT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_credit_tx_user ON credit_transactions(user_id);
CREATE INDEX IF NOT EXISTS idx_credit_tx_user_created ON credit_transactions(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_credit_tx_type ON credit_transactions(type);
CREATE INDEX IF NOT EXISTS idx_credit_tx_status
    ON credit_transactions(status, created_at) WHERE status = 'reserved';
CREATE INDEX IF NOT EXISTS idx_credit_tx_settling
    ON credit_transactions(status, created_at) WHERE status = 'settling';
-- "What has this user already paid for this piece of work".
CREATE INDEX IF NOT EXISTS idx_credit_tx_reference
    ON credit_transactions (user_id, reference_type, reference_id)
    WHERE reference_id IS NOT NULL;

-- ── Stripe webhook idempotency ─────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS webhook_events (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    stripe_event_id TEXT UNIQUE NOT NULL,
    event_type      TEXT NOT NULL,
    payload         JSONB NOT NULL,
    status          TEXT NOT NULL DEFAULT 'received'
                    CHECK (status IN ('received', 'processed', 'failed')),
    error_message   TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    processed_at    TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_webhook_events_status ON webhook_events(status);

-- ── LLM usage (written by app.llm.metering) ────────────────────────────────

CREATE TABLE IF NOT EXISTS llm_usage (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id               UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    session_id            UUID,
    model                 TEXT NOT NULL,
    input_tokens          INTEGER NOT NULL,
    output_tokens         INTEGER NOT NULL,
    cache_read_tokens     INTEGER DEFAULT 0,
    cache_creation_tokens INTEGER DEFAULT 0,
    cost_usd              NUMERIC(10,6) NOT NULL,
    turn_number           SMALLINT,
    stop_reason           TEXT,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    provider              TEXT,
    duration_ms           INTEGER,
    endpoint              TEXT,     -- free-text caller label
    success               BOOLEAN DEFAULT TRUE,
    error_class           TEXT,
    failover_cause        TEXT      -- why the chain reached this provider
);

CREATE INDEX IF NOT EXISTS idx_llm_usage_user ON llm_usage(user_id);
CREATE INDEX IF NOT EXISTS idx_llm_usage_session ON llm_usage(session_id);
CREATE INDEX IF NOT EXISTS idx_llm_usage_created ON llm_usage(created_at);
CREATE INDEX IF NOT EXISTS idx_llm_usage_endpoint_created ON llm_usage(endpoint, created_at DESC);

-- Cost derived from tokens and the current price list (keep in sync with
-- app/llm/pricing.py); correcting it corrects history. cost_usd_stored is the
-- write-time value.
CREATE OR REPLACE VIEW llm_usage_costed AS
WITH prices(model, input_per_m, output_per_m, cache_read_per_m, cache_creation_per_m) AS (
    VALUES
        ('claude-sonnet-4-6',          3.0,   15.0,  0.30,  3.75),
        ('claude-haiku-4-5-20251001',  0.80,  4.0,   0.08,  1.0),
        ('claude-opus-4-8',            5.0,   25.0,  0.50,  6.25),
        ('deepseek-chat',              0.3,   1.2,   0.0,   0.0),
        ('deepseek-reasoner',          0.3,   1.2,   0.0,   0.0),
        ('deepseek-flash',             0.3,   1.2,   0.006, 0.0),
        ('deepseek-v4-flash',          0.3,   1.2,   0.006, 0.0),
        ('deepseek-v4-pro',            1.32,  3.96,  0.044, 0.0)
)
SELECT
    u.id,
    u.user_id,
    u.session_id,
    u.model,
    u.input_tokens,
    u.output_tokens,
    u.cache_read_tokens,
    u.cache_creation_tokens,
    COALESCE(
        u.input_tokens / 1e6 * p.input_per_m
        + u.output_tokens / 1e6 * p.output_per_m
        + COALESCE(u.cache_read_tokens, 0) / 1e6 * p.cache_read_per_m
        + COALESCE(u.cache_creation_tokens, 0) / 1e6 * p.cache_creation_per_m,
        u.cost_usd
    )::numeric(10,6) AS cost_usd,
    u.cost_usd AS cost_usd_stored,
    u.turn_number,
    u.stop_reason,
    u.created_at,
    u.provider,
    u.duration_ms,
    u.endpoint,
    u.success,
    u.error_class,
    u.failover_cause
FROM llm_usage u
LEFT JOIN prices p ON p.model = u.model;

-- ── Vendor (non-LLM) paid calls — written by billing/paid_call (M1) ────────

CREATE TABLE IF NOT EXISTS vendor_calls (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     UUID REFERENCES "user"(id) ON DELETE CASCADE,
    vendor      TEXT NOT NULL,
    operation   TEXT NOT NULL,
    cost_usd    NUMERIC(10,6) NOT NULL DEFAULT 0,
    units       INTEGER NOT NULL DEFAULT 1,
    success     BOOLEAN NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_vendor_calls_user_created ON vendor_calls(user_id, created_at DESC);

-- ── Personal API keys (sbk_…) — only the SHA-256 is stored ─────────────────

CREATE TABLE IF NOT EXISTS user_api_keys (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id    UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    key_hash   TEXT NOT NULL UNIQUE CHECK (key_hash ~ '^[0-9a-f]{64}$'),
    label      TEXT NOT NULL CHECK (char_length(label) BETWEEN 1 AND 120),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    revoked_at TIMESTAMPTZ   -- soft delete; the verifier filters IS NULL
);

CREATE INDEX IF NOT EXISTS idx_user_api_keys_owner ON user_api_keys(user_id);

-- ============================================================================
-- Credit functions. Each runs in one implicit transaction: balance and ledger
-- can never disagree.
-- ============================================================================

-- Returns the new balance, or -1 (no row written) when credits are short.
CREATE OR REPLACE FUNCTION deduct_credits(
    p_user_id        UUID,
    p_amount         INT,
    p_reference_type TEXT  DEFAULT NULL,
    p_reference_id   TEXT  DEFAULT NULL,
    p_tool_name      TEXT  DEFAULT NULL,
    p_session_id     UUID  DEFAULT NULL,
    p_description    TEXT  DEFAULT NULL
)
RETURNS INT
LANGUAGE plpgsql
AS $$
DECLARE
    new_balance INT;
BEGIN
    UPDATE user_credits
    SET credits_remaining = credits_remaining - p_amount,
        updated_at = NOW()
    WHERE user_id = p_user_id
      AND credits_remaining >= p_amount
    RETURNING credits_remaining INTO new_balance;

    IF NOT FOUND THEN
        RETURN -1;
    END IF;

    INSERT INTO credit_transactions (
        user_id, type, amount, balance_after,
        reference_type, reference_id, description,
        tool_name, session_id
    ) VALUES (
        p_user_id, 'deduction', p_amount, new_balance,
        p_reference_type, p_reference_id, p_description,
        p_tool_name, p_session_id
    );

    RETURN new_balance;
END;
$$;

CREATE OR REPLACE FUNCTION increment_credits(
    p_user_id        UUID,
    p_amount         INT,
    p_type           TEXT  DEFAULT 'refund',
    p_reference_type TEXT  DEFAULT NULL,
    p_reference_id   TEXT  DEFAULT NULL,
    p_tool_name      TEXT  DEFAULT NULL,
    p_session_id     UUID  DEFAULT NULL,
    p_description    TEXT  DEFAULT NULL
)
RETURNS INT
LANGUAGE plpgsql
AS $$
DECLARE
    new_balance INT;
BEGIN
    IF p_type NOT IN ('refund', 'renewal', 'purchase', 'bonus', 'adjustment') THEN
        RAISE EXCEPTION 'increment_credits: p_type must be one of refund/renewal/purchase/bonus/adjustment, got %', p_type;
    END IF;

    UPDATE user_credits
    SET credits_remaining = credits_remaining + p_amount,
        updated_at = NOW()
    WHERE user_id = p_user_id
    RETURNING credits_remaining INTO new_balance;

    IF NOT FOUND THEN
        -- Defensive: the signup hook should have created the row.
        INSERT INTO user_credits (user_id, credits_remaining, created_at, updated_at)
        VALUES (p_user_id, p_amount, NOW(), NOW())
        RETURNING credits_remaining INTO new_balance;
    END IF;

    INSERT INTO credit_transactions (
        user_id, type, amount, balance_after,
        reference_type, reference_id, description,
        tool_name, session_id
    ) VALUES (
        p_user_id, p_type, p_amount, new_balance,
        p_reference_type, p_reference_id, p_description,
        p_tool_name, p_session_id
    );

    RETURN new_balance;
END;
$$;

-- Two-phase: reserve (balance moves now) → commit | release | settle_with_slack.
-- Returns the reservation id, or NULL (nothing written) when credits are short.
CREATE OR REPLACE FUNCTION reserve_credits(
    p_user_id        UUID,
    p_amount         INT,
    p_reference_type TEXT  DEFAULT NULL,
    p_reference_id   TEXT  DEFAULT NULL,
    p_tool_name      TEXT  DEFAULT NULL,
    p_session_id     UUID  DEFAULT NULL,
    p_description    TEXT  DEFAULT NULL
)
RETURNS UUID
LANGUAGE plpgsql
AS $$
DECLARE
    new_balance     INT;
    reservation_id  UUID;
BEGIN
    UPDATE user_credits
    SET credits_remaining = credits_remaining - p_amount,
        updated_at = NOW()
    WHERE user_id = p_user_id
      AND credits_remaining >= p_amount
    RETURNING credits_remaining INTO new_balance;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    INSERT INTO credit_transactions (
        user_id, type, amount, balance_after, status,
        reference_type, reference_id, description,
        tool_name, session_id
    ) VALUES (
        p_user_id, 'reservation', p_amount, new_balance, 'reserved',
        p_reference_type, p_reference_id, p_description,
        p_tool_name, p_session_id
    )
    RETURNING id INTO reservation_id;

    RETURN reservation_id;
END;
$$;

-- No balance change (already moved at reserve). Accepts 'settling' too, so a
-- hold taken away from the reaper is still settleable. Idempotent.
CREATE OR REPLACE FUNCTION commit_reservation(p_reservation_id UUID)
RETURNS BOOLEAN
LANGUAGE plpgsql
AS $$
DECLARE
    rows_affected INT;
BEGIN
    UPDATE credit_transactions
    SET status = 'committed',
        type = 'deduction'
    WHERE id = p_reservation_id
      AND status IN ('reserved', 'settling')
      AND type = 'reservation';

    GET DIAGNOSTICS rows_affected = ROW_COUNT;
    RETURN rows_affected > 0;
END;
$$;

-- Restores balance, marks the hold released, writes a compensating refund.
CREATE OR REPLACE FUNCTION release_reservation(p_reservation_id UUID)
RETURNS BOOLEAN
LANGUAGE plpgsql
AS $$
DECLARE
    rsv             credit_transactions%ROWTYPE;
    new_balance     INT;
BEGIN
    -- Row lock: concurrent commit/release can't double-process it.
    SELECT * INTO rsv FROM credit_transactions
        WHERE id = p_reservation_id
          AND status = 'reserved'
          AND type = 'reservation'
        FOR UPDATE;

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    UPDATE credit_transactions
        SET status = 'released'
        WHERE id = p_reservation_id;

    UPDATE user_credits
        SET credits_remaining = credits_remaining + rsv.amount,
            updated_at = NOW()
        WHERE user_id = rsv.user_id
        RETURNING credits_remaining INTO new_balance;

    INSERT INTO credit_transactions (
        user_id, type, amount, balance_after,
        reference_type, reference_id, description,
        tool_name, session_id
    ) VALUES (
        rsv.user_id, 'refund', rsv.amount, new_balance,
        rsv.reference_type, rsv.reference_id,
        'Released reservation ' || p_reservation_id::TEXT,
        rsv.tool_name, rsv.session_id
    );

    RETURN TRUE;
END;
$$;

-- Takes a hold away from the reaper (work landed, settle failed). No balance
-- movement; only an open reservation can move.
CREATE OR REPLACE FUNCTION mark_reservation_settling(p_reservation_id UUID)
RETURNS BOOLEAN
LANGUAGE plpgsql
AS $$
DECLARE
    rows_affected INT;
BEGIN
    UPDATE credit_transactions
    SET status = 'settling'
    WHERE id = p_reservation_id
      AND status = 'reserved'
      AND type = 'reservation';

    GET DIAGNOSTICS rows_affected = ROW_COUNT;
    RETURN rows_affected > 0;
END;
$$;

-- Beat janitor: turn old 'settling' holds into the deduction they stand for.
CREATE OR REPLACE FUNCTION commit_settling_reservations(p_older_than_minutes INT)
RETURNS INT
LANGUAGE plpgsql
AS $$
DECLARE
    rid UUID;
    committed INT := 0;
BEGIN
    FOR rid IN
        SELECT id FROM credit_transactions
            WHERE status = 'settling'
              AND type = 'reservation'
              AND created_at < NOW() - (p_older_than_minutes || ' minutes')::INTERVAL
            FOR UPDATE SKIP LOCKED
    LOOP
        IF commit_reservation(rid) THEN
            committed := committed + 1;
        END IF;
    END LOOP;

    RETURN committed;
END;
$$;

-- Close a hold and refund its unused worst-case allowance, atomically. The
-- reservation row serialises retries; the settlement_* markers make a retry
-- after a lost response return the original result instead of paying twice.
CREATE OR REPLACE FUNCTION settle_reservation_with_slack(
    p_reservation_id UUID,
    p_refund_amount INT
)
RETURNS JSONB
LANGUAGE plpgsql
AS $$
DECLARE
    rsv credit_transactions%ROWTYPE;
    existing_refund credit_transactions%ROWTYPE;
    actual_refund INT := 0;
    final_balance INT;
BEGIN
    SELECT * INTO rsv
    FROM credit_transactions
    WHERE id = p_reservation_id
    FOR UPDATE;

    IF NOT FOUND OR rsv.status = 'released' THEN
        RETURN NULL;
    END IF;

    IF p_refund_amount < 0 OR p_refund_amount > rsv.amount THEN
        RAISE EXCEPTION
            'settle_reservation_with_slack: refund % outside reservation amount %',
            p_refund_amount, rsv.amount;
    END IF;

    IF rsv.settlement_net_credits IS NOT NULL THEN
        IF rsv.settlement_refund_amount <> p_refund_amount THEN
            RAISE EXCEPTION
                'settle_reservation_with_slack: retry amount % differs from prior refund %',
                p_refund_amount, rsv.settlement_refund_amount;
        END IF;
        RETURN jsonb_build_object(
            'net_credits', rsv.settlement_net_credits,
            'remaining', rsv.settlement_balance_after
        );
    END IF;

    IF rsv.status IN ('reserved', 'settling') AND rsv.type = 'reservation' THEN
        UPDATE credit_transactions
        SET status = 'committed', type = 'deduction'
        WHERE id = p_reservation_id;
    ELSIF NOT (rsv.status = 'committed' AND rsv.type = 'deduction') THEN
        RETURN NULL;
    END IF;

    SELECT * INTO existing_refund
    FROM credit_transactions
    WHERE user_id = rsv.user_id
      AND type = 'refund'
      AND reference_type = 'reservation.slack'
      AND reference_id = p_reservation_id::TEXT
    LIMIT 1;

    IF FOUND THEN
        IF existing_refund.amount <> p_refund_amount THEN
            RAISE EXCEPTION
                'settle_reservation_with_slack: retry amount % differs from prior refund %',
                p_refund_amount, existing_refund.amount;
        END IF;
        actual_refund := existing_refund.amount;
        final_balance := existing_refund.balance_after;
    ELSIF p_refund_amount > 0 THEN
        UPDATE user_credits
        SET credits_remaining = credits_remaining + p_refund_amount,
            updated_at = NOW()
        WHERE user_id = rsv.user_id
        RETURNING credits_remaining INTO final_balance;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'settle_reservation_with_slack: balance missing for user %',
                rsv.user_id;
        END IF;

        INSERT INTO credit_transactions (
            user_id, type, amount, balance_after,
            reference_type, reference_id, description,
            tool_name, session_id
        ) VALUES (
            rsv.user_id, 'refund', p_refund_amount, final_balance,
            'reservation.slack', p_reservation_id::TEXT,
            'Refund: reserved worst case, billed fewer rows',
            rsv.tool_name, rsv.session_id
        );
        actual_refund := p_refund_amount;
    END IF;

    IF p_refund_amount = 0 THEN
        SELECT credits_remaining INTO final_balance
        FROM user_credits
        WHERE user_id = rsv.user_id
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION
                'settle_reservation_with_slack: balance missing for user %',
                rsv.user_id;
        END IF;
    END IF;

    UPDATE credit_transactions
    SET settlement_refund_amount = actual_refund,
        settlement_net_credits = rsv.amount - actual_refund,
        settlement_balance_after = final_balance
    WHERE id = p_reservation_id;

    RETURN jsonb_build_object(
        'net_credits', rsv.amount - actual_refund,
        'remaining', final_balance
    );
END;
$$;

-- Beat janitor: release holds still 'reserved' after N minutes, returning the
-- ids (tells a reaper/commit race from a repository failure, the earlier implementation #3138).
CREATE OR REPLACE FUNCTION reap_stale_reservations_ids(p_older_than_minutes INT)
RETURNS SETOF UUID
LANGUAGE plpgsql
AS $$
DECLARE
    rid UUID;
BEGIN
    FOR rid IN
        SELECT id FROM credit_transactions
            WHERE status = 'reserved'
              AND type = 'reservation'
              AND created_at < NOW() - (p_older_than_minutes || ' minutes')::INTERVAL
            FOR UPDATE SKIP LOCKED
    LOOP
        -- Only the ones actually released are returned.
        IF release_reservation(rid) THEN
            RETURN NEXT rid;
        END IF;
    END LOOP;

    RETURN;
END;
$$;

CREATE OR REPLACE FUNCTION reap_stale_reservations(p_older_than_minutes INT)
RETURNS INT
LANGUAGE sql
AS $$
    SELECT count(*)::INT FROM reap_stale_reservations_ids(p_older_than_minutes);
$$;


-- ── schema_agent.sql ──

-- ============================================================================
-- feature/m1-agent: chat, jobs, lists. Runs after schema.sql. No RLS: the api
-- filters every query by user_id. Idempotent.
-- ============================================================================

-- ── Chat ───────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS chat_sessions (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    title       TEXT,
    pinned_at   TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_chat_sessions_user ON chat_sessions(user_id, updated_at DESC);

-- One row per turn side. tool_calls: [{id, name, input, result, credits_used,
-- verdict}], the shape the earlier implementation FE session loader reads back.
CREATE TABLE IF NOT EXISTS chat_messages (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id     UUID NOT NULL REFERENCES chat_sessions(id) ON DELETE CASCADE,
    user_id        UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    role           TEXT NOT NULL CHECK (role IN ('user', 'assistant')),
    content        TEXT NOT NULL DEFAULT '',
    tool_calls     JSONB,
    sources        JSONB,
    credits_used   INTEGER NOT NULL DEFAULT 0,
    status         TEXT CHECK (status IN ('success', 'partial', 'failed')),
    terminal_code  TEXT,
    job_id         UUID,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_chat_messages_session ON chat_messages(session_id, created_at);

-- ── Lists (List/Row/Column: List / Column / Row) ─────────────────────────────

CREATE TABLE IF NOT EXISTS lists (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id          UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    chat_session_id  UUID REFERENCES chat_sessions(id) ON DELETE SET NULL,
    name             TEXT NOT NULL,
    entity           TEXT NOT NULL CHECK (entity IN ('company', 'person')),
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_lists_user ON lists(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_lists_session ON lists(chat_session_id);

CREATE TABLE IF NOT EXISTS list_columns (
    list_id   UUID NOT NULL REFERENCES lists(id) ON DELETE CASCADE,
    key       TEXT NOT NULL,
    label     TEXT NOT NULL,
    kind      TEXT NOT NULL CHECK (kind IN ('code', 'score', 'static')),
    position  INTEGER NOT NULL,
    config    JSONB NOT NULL DEFAULT '{}',
    PRIMARY KEY (list_id, key)
);

CREATE TABLE IF NOT EXISTS list_rows (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    -- insertion order; the rows endpoint pages on it
    seq              BIGINT GENERATED ALWAYS AS IDENTITY,
    list_id          UUID NOT NULL REFERENCES lists(id) ON DELETE CASCADE,
    cells            JSONB NOT NULL DEFAULT '{}',
    relevance_score  NUMERIC(5,2),
    dedupe_key       TEXT,
    excluded         BOOLEAN NOT NULL DEFAULT false,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (list_id, dedupe_key)
);

CREATE INDEX IF NOT EXISTS idx_list_rows_list_seq ON list_rows(list_id, seq);

-- ── Jobs: one per chat turn, run by the Celery task run_job ────────────────

CREATE TABLE IF NOT EXISTS jobs (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id           UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    chat_session_id   UUID REFERENCES chat_sessions(id) ON DELETE SET NULL,
    kind              TEXT NOT NULL DEFAULT 'chat_turn',
    status            TEXT NOT NULL DEFAULT 'queued' CHECK (status IN (
                          'queued', 'running', 'needs_input', 'succeeded', 'failed', 'cancelled'
                      )),
    phase             TEXT,
    progress_done     INTEGER NOT NULL DEFAULT 0,
    progress_total    INTEGER NOT NULL DEFAULT 0,
    list_id           UUID REFERENCES lists(id) ON DELETE SET NULL,
    reservation_id    UUID,
    credits_reserved  INTEGER NOT NULL DEFAULT 0,
    credits_spent     INTEGER NOT NULL DEFAULT 0,
    error             TEXT,
    result            JSONB,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    started_at        TIMESTAMPTZ,
    finished_at       TIMESTAMPTZ,
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_jobs_user_created ON jobs(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_jobs_session ON jobs(chat_session_id, created_at DESC);
-- At most one live job per user: a second send while one runs gets a 409.
CREATE UNIQUE INDEX IF NOT EXISTS uq_jobs_one_active_per_user
    ON jobs(user_id) WHERE status IN ('queued', 'running');

-- ── Projects: group chats and their lists (List/Row/Column) ──────────────────

CREATE TABLE IF NOT EXISTS projects (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    name        TEXT NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_projects_user ON projects(user_id, created_at);

-- Nullable: rows written before projects existed get one from the backfill below.
ALTER TABLE chat_sessions ADD COLUMN IF NOT EXISTS project_id UUID REFERENCES projects(id) ON DELETE CASCADE;
-- What the chat was started to do (#209); fixed at creation, null = a plain chat.
ALTER TABLE chat_sessions ADD COLUMN IF NOT EXISTS goal TEXT CHECK (goal IN ('campaign'));
ALTER TABLE lists ADD COLUMN IF NOT EXISTS project_id UUID REFERENCES projects(id) ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS idx_chat_sessions_project ON chat_sessions(project_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_lists_project ON lists(project_id, created_at DESC);

-- Backfill: one default project per user with unassigned sessions or lists.
INSERT INTO projects (user_id, name)
SELECT u.user_id, 'Il mio progetto' FROM (
    SELECT user_id FROM chat_sessions WHERE project_id IS NULL
    UNION SELECT user_id FROM lists WHERE project_id IS NULL
) u
WHERE NOT EXISTS (SELECT 1 FROM projects p WHERE p.user_id = u.user_id);
UPDATE chat_sessions s SET project_id = (SELECT p.id FROM projects p WHERE p.user_id = s.user_id ORDER BY p.created_at LIMIT 1)
WHERE s.project_id IS NULL;
UPDATE lists l SET project_id = coalesce(
    (SELECT s.project_id FROM chat_sessions s WHERE s.id = l.chat_session_id),
    (SELECT p.id FROM projects p WHERE p.user_id = l.user_id ORDER BY p.created_at LIMIT 1))
WHERE l.project_id IS NULL;


-- ── schema_ai_columns.sql ──

-- AI (research) columns, E3 #56/#57. Runs after schema_agent.sql. Re-runnable.
--
-- Existing database upgrade (back up first, then apply before deploying code):
--   docker compose exec -T postgres sh -c 'psql -X -v ON_ERROR_STOP=1 --single-transaction -U "$POSTGRES_USER" -d "$POSTGRES_DB"' < api/db/schema_ai_columns.sql

-- list_columns.kind gains 'ai'. CREATE TABLE IF NOT EXISTS never touches an
-- existing CHECK, so replace it by its default name. config of an 'ai' column:
-- {prompt, fill: {status: queued|running|done|failed, error, queued_at, filled, empty, failed, credits}}.
ALTER TABLE list_columns DROP CONSTRAINT IF EXISTS list_columns_kind_check;
ALTER TABLE list_columns ADD CONSTRAINT list_columns_kind_check
    CHECK (kind IN ('ai', 'code', 'score', 'static'));

-- Per-cell provenance, keyed by column key. Kept out of `cells` so exports,
-- dedupe and row merges never see it:
-- {"<key>": {"status": "filled|empty|failed", "source": {"url", "title"}|null, "error": str|null, "at": iso}}.
ALTER TABLE list_rows ADD COLUMN IF NOT EXISTS cell_meta JSONB NOT NULL DEFAULT '{}';


-- ── schema_ask_user.sql ──

-- ask_user (#40): the question + options an assistant message ended on; the
-- job of that turn is 'needs_input'. Additive, safe on existing databases.
ALTER TABLE chat_messages ADD COLUMN IF NOT EXISTS question JSONB;


-- ── schema_billing.sql ──

-- ============================================================================
-- m1-billing-admin. Runs after better-auth.sql + schema.sql. Idempotent.
-- ============================================================================

-- ── Stripe top-ups: one row per paid Checkout Session ──────────────────────
-- Revenue source for /v1/admin/costs. The unique session id is the second
-- idempotency fence after webhook_events (two events, one session).

CREATE TABLE IF NOT EXISTS purchases (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id            UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    stripe_session_id  TEXT NOT NULL UNIQUE,
    stripe_payment_intent TEXT,
    pack_id            TEXT NOT NULL,
    credits            INTEGER NOT NULL CHECK (credits > 0),
    amount_cents       INTEGER NOT NULL,
    currency           TEXT NOT NULL DEFAULT 'eur',
    -- Set from charge.refunded. No automatic credit claw-back: admin decides.
    refunded_cents     INTEGER NOT NULL DEFAULT 0,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_purchases_created ON purchases(created_at);
CREATE INDEX IF NOT EXISTS idx_purchases_payment_intent ON purchases(stripe_payment_intent);

-- ── Kill switches / admin settings ─────────────────────────────────────────
-- Keys: vendor_disabled:<provider>, channel_disabled:<channel>. Read through
-- app.admin.settings.is_disabled (30s cache).

CREATE TABLE IF NOT EXISTS settings (
    key         TEXT PRIMARY KEY,
    value       JSONB NOT NULL,
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by  UUID REFERENCES "user"(id) ON DELETE SET NULL
);

-- ── Stripe customers and subscriptions ─────────────────────────────────────
-- One Stripe Customer per user: carries address + VAT id (Stripe Tax), saved
-- card, invoices and the portal. Created on the first checkout.

CREATE TABLE IF NOT EXISTS billing_customers (
    user_id             UUID PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,
    stripe_customer_id  TEXT NOT NULL UNIQUE,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Mirror of customer.subscription.* events. event_created drops stale
-- out-of-order deliveries (Stripe does not guarantee order).
CREATE TABLE IF NOT EXISTS subscriptions (
    stripe_subscription_id TEXT PRIMARY KEY,
    user_id                UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    plan_id                TEXT,          -- NULL: price not in BILLING_PLANS
    status                 TEXT NOT NULL, -- Stripe status: active, past_due, canceled, …
    current_period_end     TIMESTAMPTZ,
    cancel_at_period_end   BOOLEAN NOT NULL DEFAULT false,
    event_created          BIGINT NOT NULL,
    updated_at             TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_subscriptions_user ON subscriptions(user_id);

-- Paid subscription invoices land in purchases too (revenue for admin costs):
-- one row per invoice, keyed by stripe_invoice_id instead of the session id.
ALTER TABLE purchases ALTER COLUMN stripe_session_id DROP NOT NULL;
ALTER TABLE purchases ADD COLUMN IF NOT EXISTS stripe_invoice_id TEXT UNIQUE;

-- ── Auto top-up (#94) ──────────────────────────────────────────────────────
-- Buys pack_id off-session when credits_remaining drops under threshold
-- (app/billing/auto_topup.py). charging_since: a charge is running, so the
-- minute scan never starts a second one. A failed charge sets enabled = false
-- and last_error (Stripe error code) until the user saves the settings again.
CREATE TABLE IF NOT EXISTS auto_topups (
    user_id         UUID PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,
    enabled         BOOLEAN NOT NULL DEFAULT false,
    awaiting_card   BOOLEAN NOT NULL DEFAULT false,  -- card setup Checkout open: its webhook switches it on
    pack_id         TEXT NOT NULL,
    threshold       INTEGER NOT NULL CHECK (threshold > 0),
    charging_since  TIMESTAMPTZ,
    last_error      TEXT,
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ── schema_campaigns.sql ──

-- M2 campaign aggregate:
-- 20260825090000, 20260903090000, target identity/refill, sender pool/window,
-- frozen copy and send lifecycle migrations. No Supabase/RLS dependencies.
-- Runs after schema_agent.sql. Re-runnable; existing DB upgrade: docs/campaign-schema.md.

CREATE TABLE IF NOT EXISTS outreach_campaigns (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_id UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    name TEXT NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 200),
    rationale TEXT NOT NULL DEFAULT '' CHECK (char_length(rationale) <= 500),
    criteria JSONB NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(criteria) = 'object'),
    status TEXT NOT NULL DEFAULT 'draft'
        CHECK (status IN ('draft', 'active', 'paused', 'stopped', 'completed')),
    -- Detailed shape is validated by outreach.domain.campaign.validate_steps.
    steps JSONB NOT NULL DEFAULT '[]' CHECK (
        CASE WHEN jsonb_typeof(steps) = 'array' THEN jsonb_array_length(steps) <= 12 ELSE false END
    ),
    approve_before_sending BOOLEAN NOT NULL DEFAULT true,
    block_active_duplicates BOOLEAN NOT NULL DEFAULT true,
    block_prior_contacts BOOLEAN NOT NULL DEFAULT true,
    sender_pool TEXT[] NOT NULL DEFAULT '{}' CHECK (
        sender_pool <@ ARRAY['google', 'microsoft']::TEXT[] AND array_position(sender_pool, NULL) IS NULL
    ),
    send_window_start_hour SMALLINT NOT NULL DEFAULT 9,
    send_window_end_hour SMALLINT NOT NULL DEFAULT 18,
    send_window_days SMALLINT[] NOT NULL DEFAULT ARRAY[0, 1, 2, 3, 4]::SMALLINT[],
    activated_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (id, owner_id),
    CHECK (send_window_start_hour >= 0 AND send_window_start_hour < send_window_end_hour
           AND send_window_end_hour <= 24),
    CHECK (cardinality(send_window_days) BETWEEN 1 AND 7
           AND send_window_days <@ ARRAY[0, 1, 2, 3, 4, 5, 6]::SMALLINT[]
           AND array_position(send_window_days, NULL) IS NULL)
);
CREATE INDEX IF NOT EXISTS outreach_campaigns_owner_created_idx
    ON outreach_campaigns(owner_id, created_at DESC);
-- The list a draft was made from (#209): the chat's draft_campaign tool reuses the newest draft per list.
ALTER TABLE outreach_campaigns ADD COLUMN IF NOT EXISTS list_id UUID REFERENCES lists(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS outreach_campaigns_list_idx ON outreach_campaigns(list_id, created_at DESC)
    WHERE list_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS outreach_campaign_targets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    campaign_id UUID NOT NULL,
    owner_id UUID NOT NULL,
    linkedin_url TEXT NOT NULL DEFAULT '' CHECK (char_length(linkedin_url) <= 500),
    email TEXT CHECK (email IS NULL OR char_length(email) <= 320),
    first_name TEXT NOT NULL DEFAULT '' CHECK (char_length(first_name) <= 200),
    last_name TEXT NOT NULL DEFAULT '' CHECK (char_length(last_name) <= 200),
    company_name TEXT NOT NULL DEFAULT '' CHECK (char_length(company_name) <= 300),
    role TEXT NOT NULL DEFAULT '' CHECK (char_length(role) <= 300),
    -- A background refill cannot enroll a sendable person without review.
    status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('active', 'draft', 'paused', 'excluded', 'replied')),
    source TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('onboarding', 'manual', 'csv', 'refill')),
    next_step INTEGER NOT NULL DEFAULT 1 CHECK (next_step BETWEEN 1 AND 13),
    replied_at TIMESTAMPTZ,
    linkedin_accepted_at TIMESTAMPTZ,
    sender_provider TEXT CHECK (sender_provider IN ('google', 'microsoft')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (id, campaign_id, owner_id),
    FOREIGN KEY (campaign_id, owner_id) REFERENCES outreach_campaigns(id, owner_id) ON DELETE CASCADE,
    CHECK (btrim(linkedin_url) <> '' OR coalesce(btrim(email), '') <> '')
);
CREATE UNIQUE INDEX IF NOT EXISTS outreach_campaign_targets_email_key
    ON outreach_campaign_targets(campaign_id, lower(btrim(email)))
    WHERE coalesce(btrim(email), '') <> '';
CREATE UNIQUE INDEX IF NOT EXISTS outreach_campaign_targets_linkedin_key
    ON outreach_campaign_targets(campaign_id,
        lower(regexp_replace(split_part(split_part(btrim(linkedin_url), '?', 1), '#', 1), '^https?://(www\.)?|^www\.|/+$', '', 'gi')))
    WHERE btrim(linkedin_url) <> '';
CREATE INDEX IF NOT EXISTS outreach_campaign_targets_campaign_status_idx
    ON outreach_campaign_targets(campaign_id, status);

CREATE TABLE IF NOT EXISTS outreach_campaign_sends (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    campaign_id UUID NOT NULL,
    owner_id UUID NOT NULL,
    target_id UUID,
    step INTEGER NOT NULL CHECK (step BETWEEN 1 AND 12),
    channel TEXT NOT NULL CHECK (channel IN ('email', 'linkedin_connect', 'linkedin_message')),
    status TEXT NOT NULL DEFAULT 'awaiting_approval'
        CHECK (status IN ('awaiting_approval', 'approved', 'sending', 'sent', 'failed', 'refused', 'skipped')),
    attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    recipient TEXT NOT NULL CHECK (char_length(btrim(recipient)) BETWEEN 1 AND 500),
    subject TEXT NOT NULL DEFAULT '' CHECK (char_length(subject) <= 300),
    -- NULL follows the template; an empty string is a frozen note-less invitation.
    body TEXT CHECK (body IS NULL OR char_length(body) <= 4000),
    provider_receipt_id TEXT CHECK (char_length(provider_receipt_id) <= 500),
    error_code TEXT CHECK (char_length(error_code) <= 100),
    -- Durable even after target deletion. Writer uses campaign:target:step.
    idempotency_key TEXT NOT NULL UNIQUE CHECK (char_length(idempotency_key) BETWEEN 1 AND 500),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    approved_at TIMESTAMPTZ,
    delivered_at TIMESTAMPTZ,
    UNIQUE (campaign_id, target_id, step),
    FOREIGN KEY (campaign_id, owner_id) REFERENCES outreach_campaigns(id, owner_id) ON DELETE CASCADE,
    FOREIGN KEY (target_id, campaign_id, owner_id)
        REFERENCES outreach_campaign_targets(id, campaign_id, owner_id) ON DELETE SET NULL (target_id),
    CHECK (status <> 'sent' OR delivered_at IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS outreach_campaign_sends_owner_created_idx
    ON outreach_campaign_sends(owner_id, created_at DESC);
CREATE INDEX IF NOT EXISTS outreach_campaign_sends_open_idx
    ON outreach_campaign_sends(campaign_id, status)
    WHERE status IN ('awaiting_approval', 'approved', 'sending', 'failed');

CREATE OR REPLACE FUNCTION touch_outreach_campaigns_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_outreach_campaigns_updated_at ON outreach_campaigns;
CREATE TRIGGER trg_outreach_campaigns_updated_at BEFORE UPDATE ON outreach_campaigns
    FOR EACH ROW EXECUTE FUNCTION touch_outreach_campaigns_updated_at();


-- ── schema_exclusions.sql ──

-- Per-user exclusions (E6, #72): who the user said never to find, enrich or contact.
-- Adapted from the earlier implementation `outreach_exclusions` (address | domain) plus company name
-- and LinkedIn URL. Values are stored normalised by app.exclusions.rules.normalise.
-- Re-runnable; on an existing DB pipe this file into psql.

CREATE TABLE IF NOT EXISTS exclusions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    kind TEXT NOT NULL CHECK (kind IN ('email', 'domain', 'company_name', 'linkedin_url')),
    value TEXT NOT NULL CHECK (char_length(value) BETWEEN 1 AND 500),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (user_id, kind, value)
);

-- #193: 'onboarding' marks a rule created from the business profile's exclusions;
-- NULL is the user's own. A profile save removes only onboarding rules.
ALTER TABLE exclusions ADD COLUMN IF NOT EXISTS source TEXT CHECK (source IN ('onboarding'));


-- ── schema_inbound.sql ──

-- E8 inbound replies (#86), reply labels (#88), opt-outs (#75), stop-on-reply (#83).
-- Runs after schema_campaigns.sql. Additive and re-runnable; existing DB: pipe this file into psql.

-- LinkedIn member id (Unipile attendee_provider_id) of a target, so a LinkedIn reply finds its
-- person even when the stored profile URL is a vanity slug. Written by the LinkedIn step (#82).
-- schema_tools_sending_linkedin.sql (#147) indexes it.
ALTER TABLE outreach_campaign_targets ADD COLUMN IF NOT EXISTS linkedin_provider_id TEXT;
CREATE INDEX IF NOT EXISTS outreach_campaign_targets_owner_email_idx
    ON outreach_campaign_targets(owner_id, lower(btrim(email))) WHERE email IS NOT NULL;
-- ponytail: the thread match (sends.message_id) rides the owner index; add one on message_id if inboxes grow.

-- One inbox for both channels. The body is the stranger's text: show it, never feed it to the
-- agent loop as an assistant message.
CREATE TABLE IF NOT EXISTS outreach_inbound_messages (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_id UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    channel TEXT NOT NULL CHECK (channel IN ('email', 'linkedin')),
    -- reply: a person; auto_reply: out-of-office/autoresponder (does not stop a sequence);
    -- unsubscribe: an explicit opt-out ("no grazie", List-Unsubscribe mailto).
    kind TEXT NOT NULL CHECK (kind IN ('reply', 'auto_reply', 'unsubscribe')),
    provider_message_id TEXT NOT NULL CHECK (char_length(provider_message_id) BETWEEN 1 AND 500),
    from_address TEXT NOT NULL DEFAULT '' CHECK (char_length(from_address) <= 500),
    from_name TEXT NOT NULL DEFAULT '' CHECK (char_length(from_name) <= 200),
    subject TEXT NOT NULL DEFAULT '' CHECK (char_length(subject) <= 300),
    body TEXT NOT NULL DEFAULT '' CHECK (char_length(body) <= 10000),
    campaign_id UUID REFERENCES outreach_campaigns(id) ON DELETE SET NULL,
    target_id UUID REFERENCES outreach_campaign_targets(id) ON DELETE SET NULL,
    label TEXT CHECK (label IN ('interested', 'meeting_request', 'not_interested', 'not_now', 'other')),
    label_source TEXT CHECK (label_source IN ('llm', 'manual')),
    -- LLM calls spent on this row; the labelling beat gives up after a few.
    label_attempts SMALLINT NOT NULL DEFAULT 0,
    notified_at TIMESTAMPTZ,
    received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (owner_id, channel, provider_message_id)
);
CREATE INDEX IF NOT EXISTS outreach_inbound_messages_owner_idx
    ON outreach_inbound_messages(owner_id, received_at DESC);
-- Added after the first review: older databases created the table without it.
ALTER TABLE outreach_inbound_messages ADD COLUMN IF NOT EXISTS label_attempts SMALLINT NOT NULL DEFAULT 0;


-- ── schema_inbox_reply.sql ──

-- E14.12 replies from the inbox (#187): read state, threading data, the agent's draft, and our replies.
-- Runs after schema_inbound.sql. Additive and re-runnable; existing DB: pipe this file into psql.

-- read_at: when the owner opened the thread («Da leggere» is read_at IS NULL). Added with a default so
-- the rows already there count as read once, then the default goes: a new reply arrives unread.
-- rfc_message_id / rfc_references: the email's own Message-ID and its chain, so our reply threads under it.
-- sender_provider_id: the LinkedIn member id (Unipile attendee_provider_id) a DM answer goes to.
-- draft_body: the agent's proposed answer, written after labelling; the owner edits it before sending.
ALTER TABLE outreach_inbound_messages
    ADD COLUMN IF NOT EXISTS read_at TIMESTAMPTZ DEFAULT now(),
    ADD COLUMN IF NOT EXISTS rfc_message_id TEXT CHECK (char_length(rfc_message_id) <= 500),
    ADD COLUMN IF NOT EXISTS rfc_references TEXT CHECK (char_length(rfc_references) <= 8000),
    ADD COLUMN IF NOT EXISTS sender_provider_id TEXT CHECK (char_length(sender_provider_id) <= 500),
    ADD COLUMN IF NOT EXISTS draft_body TEXT CHECK (char_length(draft_body) <= 4000);
ALTER TABLE outreach_inbound_messages ALTER COLUMN read_at DROP DEFAULT;
CREATE INDEX IF NOT EXISTS outreach_inbound_messages_unread_idx
    ON outreach_inbound_messages(owner_id) WHERE read_at IS NULL;

-- One row per answer the owner sent from the inbox. `sending` is the claim taken before the provider
-- call (one at a time per thread); `unknown` is a provider outcome we cannot know (maybe delivered,
-- never resent). The mailbox's daily cap counts `sending` and `sent` rows alongside campaign sends.
CREATE TABLE IF NOT EXISTS outreach_inbox_replies (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_id UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    inbound_id UUID NOT NULL REFERENCES outreach_inbound_messages(id) ON DELETE CASCADE,
    channel TEXT NOT NULL CHECK (channel IN ('email', 'linkedin')),
    sender_provider TEXT NOT NULL CHECK (sender_provider IN ('google', 'microsoft', 'unipile')),
    recipient TEXT NOT NULL CHECK (char_length(btrim(recipient)) BETWEEN 1 AND 500),
    subject TEXT NOT NULL DEFAULT '' CHECK (char_length(subject) <= 300),
    body TEXT NOT NULL CHECK (char_length(btrim(body)) BETWEEN 1 AND 4000),
    status TEXT NOT NULL DEFAULT 'sending' CHECK (status IN ('sending', 'sent', 'failed', 'unknown')),
    error_code TEXT CHECK (char_length(error_code) <= 100),
    message_id TEXT CHECK (char_length(message_id) <= 500),
    provider_receipt_id TEXT CHECK (char_length(provider_receipt_id) <= 500),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    delivered_at TIMESTAMPTZ,
    CHECK (status <> 'sent' OR delivered_at IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS outreach_inbox_replies_inbound_idx ON outreach_inbox_replies(inbound_id, created_at);
CREATE INDEX IF NOT EXISTS outreach_inbox_replies_mailbox_day_idx
    ON outreach_inbox_replies(owner_id, sender_provider, created_at) WHERE status IN ('sending', 'sent');
-- A double click sends once: a second claim on the same thread waits for the first to settle.
CREATE UNIQUE INDEX IF NOT EXISTS outreach_inbox_replies_one_sending
    ON outreach_inbox_replies(inbound_id) WHERE status = 'sending';


-- ── schema_job_retry.sql ──

ALTER TABLE jobs ADD COLUMN IF NOT EXISTS retry_of UUID REFERENCES jobs(id) ON DELETE SET NULL;
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS retry_stage INTEGER;


-- ── schema_job_timing.sql ──

-- Additive timing field for the first row a job inserts.
-- Re-runnable; existing database upgrade: docs/job-timing-schema.md.
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS first_row_at TIMESTAMPTZ;


-- ── schema_memory.sql ──

-- One personal memory document per user. Re-runnable; existing database
-- upgrade: docs/memory-schema.md.
CREATE TABLE IF NOT EXISTS user_memory_doc (
    user_id UUID PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,
    body TEXT NOT NULL DEFAULT '',
    locked BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT user_memory_doc_body_length CHECK (char_length(body) BETWEEN 0 AND 8000)
);


-- ── schema_notifications.sql ──

-- E14.7 notifications (#173): the bell panel, per-user channel settings, urgent emails and the digest.
-- Runs after schema.sql ("user"). Additive and re-runnable; existing DB: pipe this file into psql.

-- One row per event the user is told about. In-app is always on: every notification lands here.
CREATE TABLE IF NOT EXISTS notifications (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    kind TEXT NOT NULL,  -- notifications_kind_check below
    -- what the item opens: an in-app path, never an absolute URL
    href TEXT NOT NULL CHECK (href LIKE '/%' AND href NOT LIKE '//%'),
    -- what the panel renders (label, channel, a sender's name for replies); never a reply's text
    data JSONB NOT NULL DEFAULT '{}',
    read_at TIMESTAMPTZ,
    -- waiting for the next digest (an urgent email over the 30-minute cap, a non-urgent reply, do-not-disturb)
    email_pending BOOLEAN NOT NULL DEFAULT false,
    emailed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- #215 adds approval_needed, search_failed and agent_question. CREATE TABLE IF NOT EXISTS never touches an
-- existing CHECK, so replace it by its default name: the same statements create it on a fresh database.
ALTER TABLE notifications DROP CONSTRAINT IF EXISTS notifications_kind_check;
ALTER TABLE notifications ADD CONSTRAINT notifications_kind_check CHECK (kind IN (
    'reply_urgent', 'reply', 'search_done', 'low_credits', 'payment_failed',
    'approval_needed', 'search_failed', 'agent_question'
));
CREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS notifications_digest_idx ON notifications(user_id) WHERE email_pending;
-- ponytail: rows are kept forever and the panel reads the newest 50; add a TTL sweep if the table grows.

-- Channel choices (merged over app.notifications.service.DEFAULTS) and the rule state, one row per user.
CREATE TABLE IF NOT EXISTS notification_settings (
    user_id UUID PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,
    -- {"<kind>": {"email": bool, "browser": bool}}; a missing kind or channel takes the default
    events JSONB NOT NULL DEFAULT '{}',
    digest BOOLEAN NOT NULL DEFAULT true,
    dnd BOOLEAN NOT NULL DEFAULT false,
    -- last poll from an open Zenbree tab (the bell): "is Zenbree closed" for the search-done email
    last_seen_at TIMESTAMPTZ,
    -- the 30-minute cap on urgent reply emails
    last_urgent_email_at TIMESTAMPTZ,
    -- set once the balance is at or above the low-credit line, cleared by the email: once per drop
    low_credits_armed BOOLEAN NOT NULL DEFAULT false,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ── schema_onboarding.sql ──

-- Onboarding (E5): one business profile per user, the segments proposed from
-- it, and when the user finished (or skipped) onboarding. Re-runnable: on an
-- existing database pipe this file into psql. No backfill is needed, the gate
-- also lets through any user who already has a chat (app/onboarding/routes.py).
CREATE TABLE IF NOT EXISTS business_profiles (
    user_id      UUID PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,
    website      TEXT,
    description  TEXT,
    profile      JSONB,
    segments     JSONB,
    completed_at TIMESTAMPTZ,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- #192: the exact Memory entry onboarding last wrote from the profile. A later
-- profile save replaces that entry only while it is still unchanged in Memory.
ALTER TABLE business_profiles ADD COLUMN IF NOT EXISTS memory_entry TEXT;

-- #193: the exclusion lines last synced into exclusions. A profile save syncs only
-- the lines that changed, so a rule the user deleted stays deleted. NULL = never synced.
ALTER TABLE business_profiles ADD COLUMN IF NOT EXISTS exclusion_lines TEXT[];


-- ── schema_pick.sql ──

-- no-results funnel (#214): the filters of the alternative the user picked; the turn runs that search first.
-- Additive, safe on existing databases.
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS pick JSONB;


-- ── schema_plan.sql ──

-- E1 plan and launch (#42 #43 #45 #49). Additive, safe on existing databases.

-- #42: what the brief asks for: build a new list, or enrich rows the user already has.
ALTER TABLE lists ADD COLUMN IF NOT EXISTS mode TEXT NOT NULL DEFAULT 'build' CHECK (mode IN ('build', 'enrich'));

-- #43: every propose_plan call writes a new version. A plan over the large-run
-- threshold waits for the user; approving it starts the turn approved_job_id,
-- whose paid tools may spend up to approved_credits.
CREATE TABLE IF NOT EXISTS list_plans (
    list_id           UUID NOT NULL REFERENCES lists(id) ON DELETE CASCADE,
    version           INTEGER NOT NULL,
    plan              JSONB NOT NULL,
    approved_at       TIMESTAMPTZ,
    approved_rows     INTEGER,
    approved_credits  INTEGER,
    approved_job_id   UUID REFERENCES jobs(id) ON DELETE SET NULL,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (list_id, version)
);

CREATE INDEX IF NOT EXISTS idx_list_plans_job ON list_plans(approved_job_id) WHERE approved_job_id IS NOT NULL;

-- #49: the approved plan's stages with their progress, [{tool, label, units, done}].
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS stages JSONB;


-- ── schema_providers.sql ──

-- One row per contact-provider lookup (email/phone waterfall), for the
-- per-provider hit rate on /admin/costs. Re-runnable; on an existing database
-- pipe this file into psql (AGENTS.md, "Database and schema changes").
CREATE TABLE IF NOT EXISTS contact_lookups (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id    UUID REFERENCES "user"(id) ON DELETE CASCADE,
    provider   TEXT NOT NULL,  -- apollo | aiark | pdl | hunter
    channel    TEXT NOT NULL CHECK (channel IN ('email', 'phone')),
    found      BOOLEAN NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_contact_lookups_created ON contact_lookups(created_at);


-- ── schema_rows.sql ──

-- Row ratings (E1.8, #46) and "add more rows" (E1.10, #48). Runs after schema_agent.sql. Re-runnable.
--
-- Existing database upgrade (additive, apply before deploying code):
--   docker compose exec -T postgres sh -c 'psql -X -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$POSTGRES_DB"' < api/db/schema_rows.sql

-- The user's verdict on a delivered row, read back by the list_row_feedback tool.
-- rating_note is the user's own words: tool-result data, never prompt text.
ALTER TABLE list_rows ADD COLUMN IF NOT EXISTS rating TEXT CHECK (rating IN ('good', 'bad'));
ALTER TABLE list_rows ADD COLUMN IF NOT EXISTS rating_note TEXT CHECK (char_length(rating_note) <= 500);

-- The last paged search that filled the list: {"tool": str, "args": {..., "page": n}}.
-- more_rows re-runs it at page n+1, so a fetched page is never bought again.
ALTER TABLE lists ADD COLUMN IF NOT EXISTS last_search JSONB;

-- Why the scorer gave relevance_score (#159): [{match, category, freshness, key}] or NULL
-- for rows scored before it. key names the cell the evidence comes from; its cell_meta
-- source, when there is one, is the link shown. Written by the agent's scoring pass.
ALTER TABLE list_rows ADD COLUMN IF NOT EXISTS score_reasons JSONB;


-- ── schema_scheduling.sql ──

-- #96. Runs after schema_campaigns.sql; re-runnable for existing databases.
CREATE TABLE IF NOT EXISTS saved_searches (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
    tool_name TEXT NOT NULL CHECK (tool_name IN ('search_people', 'search_companies')),
    tool_input JSONB NOT NULL CHECK (jsonb_typeof(tool_input) = 'object'),
    list_id UUID NOT NULL REFERENCES lists(id) ON DELETE CASCADE,
    campaign_id UUID,
    cadence TEXT NOT NULL CHECK (cadence IN ('daily', 'weekly')),
    next_run_at TIMESTAMPTZ NOT NULL,
    enabled BOOLEAN NOT NULL DEFAULT true,
    budget_credits_per_run INTEGER NOT NULL DEFAULT 1 CHECK (budget_credits_per_run = 1),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ,
    UNIQUE(id, user_id),
    FOREIGN KEY (campaign_id, user_id) REFERENCES outreach_campaigns(id, owner_id) ON DELETE CASCADE,
    CHECK (campaign_id IS NULL OR tool_name = 'search_people')
);
CREATE INDEX IF NOT EXISTS saved_searches_due ON saved_searches(next_run_at) WHERE enabled AND deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS saved_search_runs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    saved_search_id UUID NOT NULL,
    user_id UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    scheduled_for TIMESTAMPTZ NOT NULL,
    status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'cancelled', 'unknown')),
    config JSONB NOT NULL,
    reservation_id UUID REFERENCES credit_transactions(id),
    credits_spent INTEGER NOT NULL DEFAULT 0 CHECK (credits_spent BETWEEN 0 AND 1),
    new_row_ids UUID[] NOT NULL DEFAULT '{}',
    pending_row_ids UUID[] NOT NULL DEFAULT '{}',
    refill_checked_at TIMESTAMPTZ,
    refill_done BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    started_at TIMESTAMPTZ,
    finished_at TIMESTAMPTZ,
    error_code TEXT,
    FOREIGN KEY(saved_search_id, user_id) REFERENCES saved_searches(id, user_id) ON DELETE CASCADE,
    UNIQUE(saved_search_id, scheduled_for)
);
CREATE UNIQUE INDEX IF NOT EXISTS saved_searches_one_run ON saved_search_runs(saved_search_id) WHERE status IN ('queued', 'running');
CREATE INDEX IF NOT EXISTS saved_searches_refill ON saved_search_runs(created_at) WHERE status = 'succeeded' AND NOT refill_done;


-- ── schema_tools.sql ──

-- ============================================================================
-- m1-tools schema. Runs after schema.sql.
--
-- user_oauth_connections: FK to "user"(id); legacy RLS, grants
-- and the outreach_campaigns sender-pool trigger dropped. M1 writes only
-- provider='unipile' rows: the Unipile account id, never a LinkedIn password
-- or cookie. google/microsoft rows (refresh tokens, Fernet) arrive in M2.
-- ============================================================================

CREATE TABLE IF NOT EXISTS user_oauth_connections (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id                 UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
    provider                TEXT NOT NULL
                            CONSTRAINT user_oauth_connections_provider_check
                            CHECK (provider IN ('google', 'microsoft', 'bullhorn', 'unipile')),
    -- Fernet ciphertext. Mailboxes: the refresh token. unipile: the account id.
    refresh_token_encrypted TEXT NOT NULL,
    granted_scopes          TEXT[] NOT NULL DEFAULT '{}',
    account_label           TEXT CHECK (account_label IS NULL OR char_length(account_label) <= 320),
    status                  TEXT NOT NULL DEFAULT 'connected'
                            CONSTRAINT user_oauth_connections_status_check
                            CHECK (status IN ('connected', 'error', 'disconnected')),
    last_used_at            TIMESTAMPTZ,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    provider_base_url       TEXT CHECK (provider_base_url IS NULL OR char_length(provider_base_url) <= 500),
    provider_account_id     TEXT CHECK (provider_account_id IS NULL OR char_length(provider_account_id) <= 500),
    status_detail           TEXT CHECK (status_detail IS NULL OR char_length(status_detail) <= 500),
    connected_at            TIMESTAMPTZ,
    sign_off                TEXT NOT NULL DEFAULT '' CHECK (char_length(sign_off) <= 500),
    dkim_selector           TEXT NOT NULL DEFAULT ''
                            CHECK (char_length(dkim_selector) <= 63 AND dkim_selector ~ '^[a-z0-9._-]*$'),
    inbound_subscription_id         TEXT,
    inbound_subscription_expires_at TIMESTAMPTZ,
    linkedin_premium            BOOLEAN,
    linkedin_premium_checked_at TIMESTAMPTZ,
    inbound_poll_cursor         TIMESTAMPTZ,
    inbound_poll_blocked_id     TEXT CHECK (inbound_poll_blocked_id IS NULL OR char_length(inbound_poll_blocked_id) <= 500),
    inbound_poll_blocked_attempts INTEGER NOT NULL DEFAULT 0,
    linkedin_account_name   TEXT CHECK (linkedin_account_name IS NULL OR char_length(linkedin_account_name) <= 200),
    display_name            TEXT NOT NULL DEFAULT '' CHECK (char_length(display_name) <= 100),
    send_timezone           TEXT CHECK (send_timezone IS NULL OR char_length(send_timezone) <= 64),
    daily_limit             INTEGER CHECK (daily_limit IS NULL OR daily_limit BETWEEN 1 AND 50),
    -- One live grant per provider per user; reconnecting upserts.
    UNIQUE (user_id, provider)
);

CREATE INDEX IF NOT EXISTS idx_user_oauth_connections_owner
    ON user_oauth_connections(user_id);
CREATE INDEX IF NOT EXISTS idx_user_oauth_connections_provider_account
    ON user_oauth_connections(provider, provider_account_id)
    WHERE provider_account_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_oauth_inbound_subscription
    ON user_oauth_connections (inbound_subscription_id)
    WHERE inbound_subscription_id IS NOT NULL;

CREATE OR REPLACE FUNCTION touch_user_oauth_connections_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_user_oauth_connections_updated_at ON user_oauth_connections;
CREATE TRIGGER trg_user_oauth_connections_updated_at
    BEFORE UPDATE ON user_oauth_connections
    FOR EACH ROW
    EXECUTE FUNCTION touch_user_oauth_connections_updated_at();


-- ── schema_tools_senders.sql ──

-- Senders page (#89). Must load after schema_tools.sql. Additive and re-runnable; to upgrade an
-- existing DB pipe this file into psql.

-- paused: the owner's switch on the senders page. The dispatcher skips a paused mailbox; nothing else
-- about the connection changes, so unpausing resumes where it stopped.
ALTER TABLE user_oauth_connections ADD COLUMN IF NOT EXISTS paused BOOLEAN NOT NULL DEFAULT false;


-- ── schema_tools_sending.sql ──

-- E7 send scheduler + email step (#80, #81). Must load after schema_campaigns.sql (it alters
-- outreach_campaign_sends only). Additive and re-runnable; existing DB upgrade: docs/campaign-schema.md.

-- message_id: RFC 5322 id on the sending mailbox domain, stored with `sending` before the provider call.
-- thread_id: the provider's thread handle (Gmail threadId), '' when it has none.
-- sender_provider: the mailbox that took the attempt; attempted_at: when it was claimed for the
-- provider call. Together they count a mailbox's daily cap.
ALTER TABLE outreach_campaign_sends
    ADD COLUMN IF NOT EXISTS message_id TEXT CHECK (char_length(message_id) <= 500),
    ADD COLUMN IF NOT EXISTS thread_id TEXT CHECK (char_length(thread_id) <= 500),
    ADD COLUMN IF NOT EXISTS sender_provider TEXT CHECK (sender_provider IN ('google', 'microsoft')),
    ADD COLUMN IF NOT EXISTS attempted_at TIMESTAMPTZ;

CREATE INDEX IF NOT EXISTS outreach_campaign_sends_mailbox_day_idx
    ON outreach_campaign_sends(owner_id, sender_provider, attempted_at)
    WHERE status IN ('sending', 'sent');
CREATE INDEX IF NOT EXISTS outreach_campaign_sends_sendable_idx
    ON outreach_campaign_sends(approved_at)
    WHERE status IN ('approved', 'failed') AND channel = 'email';


-- ── schema_tools_sending_linkedin.sql ──

-- E7.6 LinkedIn step (#82). Loads after schema_tools_sending.sql (it replaces that file's
-- sender_provider check). Additive and re-runnable; existing DB upgrade: docs/campaign-schema.md.

-- linkedin_provider_id (declared in schema_inbound.sql, which loads first): the Unipile id of the
-- invited profile, so an acceptance webhook (`new_relation`, keyed by that id) finds the targets it answers.
CREATE INDEX IF NOT EXISTS outreach_campaign_targets_linkedin_provider_idx
    ON outreach_campaign_targets(owner_id, linkedin_provider_id)
    WHERE linkedin_provider_id IS NOT NULL;

-- A LinkedIn attempt goes out through the owner's Unipile account. Replaces the live
-- ('google', 'microsoft') check by name, so a replay ends with the same single constraint.
ALTER TABLE outreach_campaign_sends DROP CONSTRAINT IF EXISTS outreach_campaign_sends_sender_provider_check;
ALTER TABLE outreach_campaign_sends ADD CONSTRAINT outreach_campaign_sends_sender_provider_check
    CHECK (sender_provider IN ('google', 'microsoft', 'unipile'));

